"""OpenAI Batch API helper module for LangExtract.

This module provides batch inference support using the OpenAI Batch API. It
handles:
- JSONL input file upload and batch job submission
- Job polling with timeout enforcement
- Result extraction and per-item error handling
- Order preservation across batch processing via ``idx-{n:06d}`` custom IDs
"""

from __future__ import annotations

import collections.abc
import dataclasses
import io
import json
import logging
import time
from typing import Any, Callable, Sequence

from langextract.core import exceptions

logger = logging.getLogger(__name__)

_ENDPOINT = "/v1/chat/completions"
_CUSTOM_ID_FMT = "idx-{n:06d}"
_BATCH_INPUT_PURPOSE = "batch"

# Terminal batch statuses that indicate the job did not complete successfully.
_TERMINAL_FAIL = frozenset({"failed", "expired", "cancelled"})
_TERMINAL_OK = "completed"

# Number of times to attempt downloading an output/error file before giving up
# when the API repeatedly returns a 403 (missing Files Read permission).
_DOWNLOAD_ATTEMPTS = 3


def _get(obj: Any, key: str, default: Any = None) -> Any:
  """Read ``key`` from a dict or object attribute, returning default if absent."""
  if obj is None:
    return default
  if isinstance(obj, collections.abc.Mapping):
    return obj.get(key, default)
  return getattr(obj, key, default)


@dataclasses.dataclass
class BatchConfig:
  """Configuration for OpenAI Batch API processing.

  Attributes:
    enabled: Whether batch mode is active.
    threshold: Minimum number of prompts required to trigger batch mode.
    completion_window: Batch completion window. Only '24h' is supported.
    poll_interval: Seconds between job status checks.
    timeout: Maximum seconds to wait for a batch job to complete. The default
      is greater than 86400 seconds (more than 24 hours) so that jobs using
      the full 24h completion window are not prematurely cancelled.
    max_requests_per_job: Maximum number of requests to place in one batch job.
    metadata: Optional metadata forwarded to the batch creation call.
    on_job_create: Optional callback invoked with each created job object.
  """

  enabled: bool = False
  threshold: int = 50
  completion_window: str = "24h"
  poll_interval: int | float = 30
  timeout: int | float = 90000
  max_requests_per_job: int = 50000
  metadata: dict | None = None
  on_job_create: Callable[[Any], None] | None = None

  def __post_init__(self) -> None:
    if self.completion_window != "24h":
      raise ValueError(
          "Unsupported completion_window "
          f"{self.completion_window!r}; only '24h' is supported."
      )

  @classmethod
  def from_dict(cls, obj: Any) -> "BatchConfig":
    """Coerce ``obj`` to a BatchConfig.

    Args:
      obj: A BatchConfig (returned unchanged), a bool (True -> enabled,
        False -> disabled), None (disabled), or a mapping of field values.

    Returns:
      A BatchConfig instance.

    Raises:
      TypeError: If ``obj`` is not a BatchConfig, bool, None, or mapping.
    """
    if isinstance(obj, cls):
      return obj
    if obj is None:
      return cls()
    if obj is True:
      return cls(enabled=True)
    if obj is False:
      return cls(enabled=False)
    if isinstance(obj, collections.abc.Mapping):
      valid_keys = {f.name for f in dataclasses.fields(cls)}
      return cls(**{k: v for k, v in obj.items() if k in valid_keys})
    raise TypeError("batch must be a mapping, bool, or BatchConfig")


def _read_content(resp: Any) -> str:
  """Extract text from a files.content() response."""
  if resp is None:
    return ""
  if isinstance(resp, bytes):
    return resp.decode("utf-8")
  if isinstance(resp, str):
    return resp
  text = getattr(resp, "text", None)
  if isinstance(text, str):
    return text
  content = getattr(resp, "content", None)
  if isinstance(content, bytes):
    return content.decode("utf-8")
  if isinstance(content, str):
    return content
  read = getattr(resp, "read", None)
  if callable(read):
    data = read()
    if isinstance(data, bytes):
      return data.decode("utf-8")
    if isinstance(data, str):
      return data
  return ""


def _is_403(error: Exception) -> bool:
  """Return True if ``error`` represents an HTTP 403 (permission) failure."""
  status = getattr(error, "status_code", None)
  if status is None:
    status = getattr(error, "code", None)
  if status == 403 or status == "403":
    return True
  return "403" in str(error)


def _download_file(client: Any, file_id: str, cfg: BatchConfig) -> str:
  """Download a batch file's contents, retrying on 403 permission errors."""
  for attempt in range(_DOWNLOAD_ATTEMPTS):
    try:
      resp = client.files.content(file_id)
      return _read_content(resp)
    except exceptions.InferenceError:
      raise
    except Exception as e:  # pylint: disable=broad-except
      if _is_403(e):
        if attempt < _DOWNLOAD_ATTEMPTS - 1:
          logger.warning(
              "Batch file download returned 403 (attempt %d/%d); retrying",
              attempt + 1,
              _DOWNLOAD_ATTEMPTS,
          )
          time.sleep(cfg.poll_interval)
          continue
        raise exceptions.InferenceRuntimeError(
            "Batch file download failed with 403 after "
            f"{_DOWNLOAD_ATTEMPTS} attempts; ensure the API key has "
            "Files Read permission",
            original=e,
        ) from e
      raise
  # Should be unreachable, but keeps the type checker satisfied.
  raise exceptions.InferenceRuntimeError("Batch file download failed")


def _extract_errors_text(errors: Any) -> str:
  """Best-effort extraction of human-readable text from a job errors field."""
  if not errors:
    return ""
  try:
    data = _get(errors, "data")
    if data is None and isinstance(errors, (list, tuple)):
      data = errors
    messages: list[str] = []
    if data:
      for item in data:
        msg = _get(item, "message")
        messages.append(str(msg) if msg is not None else str(item))
    if messages:
      return "; ".join(messages)
    msg = _get(errors, "message")
    if msg is not None:
      return str(msg)
    return str(errors)
  except Exception:  # pylint: disable=broad-except
    return ""


